172	void glshim_clear(ZBuffer *zb, GLint clear_z, GLint z, GLint clear_color,
173	                  GLint r, GLint g, GLint b) {
174	  if (zb != g_zb) { /* not opened through glshim_open: the stock clear */
175	    ZB_clear(zb, clear_z, z, clear_color, r, g, b);
176	    return;
177	  }
178	#ifdef GL_PROFILE
179	  const uint32_t prof_start = glshim_prof_now();
180	#endif
181	  const Box all = whole_canvas();
182	  if (clear_color) {
183	    const PIXEL color = RGB_TO_PIXEL(r, g, b);
184	    const Box area = g_color_valid && color == g_clear_color ? g_color_box : all;
185	    for (int y = area.y0; y <= area.y1; y++) {
186	      int x0 = area.x0, x1 = area.x1;
187	      if (visible_part(y, &x0, &x1))
188	        fill_pixels((uint16_t *)((GLbyte *)zb->pbuf + y * zb->linesize) + x0, color,
189	                    x1 - x0 + 1);
190	    }
191	    box_add(&g_swap_erased, area);
192	    g_color_box = kEmptyBox;
193	    g_color_valid = true;
194	    g_clear_color = color;
195	  }
196	  if (clear_z) {
197	    if (zb->depth_test) {
198	      g_z_deferred = false;
199	      clear_depth(zb, z);
200	    } else {
201	      g_z_deferred = true;
202	      g_deferred_z = z;
203	    }
204	  }
205	#ifdef GL_PROFILE
206	  glshim_prof_add(GLPROF_CLEAR, prof_start);
207	#endif
208	}
