306	/* Scale 2: every pixel of this frame's erased and drawn boxes becomes a 2 by
307	 * 2 block of the canvas, and the doubled box is marked dirty. */
308	static void double_into_canvas(void) {
309	  Box b = g_swap_erased;
310	  box_add(&b, g_swap_drawn);
311	  g_swap_drawn = g_swap_erased = kEmptyBox;
312	#ifdef GL_PROFILE
313	  glshim_prof_frames++;
314	#endif
315	  if (box_empty(b)) return;
316	  for (int y = b.y0; y <= b.y1; y++) {
317	    const PIXEL *src = (const PIXEL *)((const GLbyte *)g_zb->pbuf + y * g_zb->linesize);
318	    uint16_t *top = g_canvas->px + (size_t)(2 * y) * g_canvas->w;
319	    uint16_t *bottom = top + g_canvas->w;
320	    int x0 = b.x0, x1 = b.x1;
321	    if (!visible_part(y, &x0, &x1)) continue;
322	    for (int x = x0; x <= x1; x++) {
323	      const uint32_t pair = (uint32_t)src[x] * 0x10001u;
324	      memcpy(top + 2 * x, &pair, sizeof pair);
325	      memcpy(bottom + 2 * x, &pair, sizeof pair);
326	    }
327	  }
328	  canvas_mark_dirty(g_canvas, 2 * b.x0, 2 * b.y0, 2 * (b.x1 - b.x0 + 1),
329	                    2 * (b.y1 - b.y0 + 1));
330	}
