532	void gluLookAt(GLdouble eyex, GLdouble eyey, GLdouble eyez, GLdouble cx,
533	               GLdouble cy, GLdouble cz, GLdouble upx, GLdouble upy,
534	               GLdouble upz) {
535	  float f[3] = {(float)(cx - eyex), (float)(cy - eyey), (float)(cz - eyez)};
536	  const float up[3] = {(float)upx, (float)upy, (float)upz};
537	  float s[3], u[3];
538	  normalize3(f);
539	  cross3(f, up, s);
540	  normalize3(s);
541	  cross3(s, f, u);
542	  /* Column-major, as glMultMatrixf takes it. */
543	  GLfloat m[16] = {s[0], u[0], -f[0], 0, s[1], u[1], -f[1], 0,
544	                   s[2], u[2], -f[2], 0, 0,    0,    0,     1};
545	  glMultMatrixf(m);
546	  glTranslatef((GLfloat)-eyex, (GLfloat)-eyey, (GLfloat)-eyez);
547	}
