70	typedef struct {
71	  atomic_int in_push, max_in_push;
72	  int count;
73	  uint32_t hash;
74	  const uint16_t *pushed_px;
75	  int dirty_rows;
76	  int16_t x0[H], x1[H];
77	} Fake;
78	static Fake fake;
