80	static uint32_t fnv(const uint16_t *px) {
81	  uint32_t h = 2166136261u;
82	  for (int i = 0; i < W * H; i++) h = (h ^ px[i]) * 16777619u;
83	  return h;
84	}
85	static int fake_push(void *ctx, Canvas *view) {
86	  Fake *f = ctx;
87	  int now = atomic_fetch_add(&f->in_push, 1) + 1;
88	  if (now > atomic_load(&f->max_in_push)) atomic_store(&f->max_in_push, now);
89	  f->pushed_px = view->px;
90	  uint32_t h = 2166136261u;
91	  f->dirty_rows = 0;
92	  for (int y = 0; y < H; y++) {
93	    for (int x = 0; x < W; x++) h = (h ^ view->px[y * W + x]) * 16777619u;
94	    int x0, x1;
95	    if (canvas_dirty_row(view, y, &x0, &x1)) {
96	      f->x0[f->dirty_rows] = (int16_t)x0;
97	      f->x1[f->dirty_rows] = (int16_t)x1;
98	      f->dirty_rows++;
99	    }
100	    if (y % 8 == 0) usleep(300);
101	  }
102	  f->hash = h;
103	  f->count++;
104	  atomic_fetch_sub(&f->in_push, 1);
105	  return f->dirty_rows;
106	}
