262	static void big_open(void) {
263	  TEST_ASSERT_EQUAL_INT(0, canvas_init(&big, BW, BW, malloc));
264	  TEST_ASSERT_EQUAL_INT(0, canvas_set_disc(&big, malloc));
265	  big_first_px = big.px;
266	  shadow = calloc((size_t)BW * BW, sizeof(uint16_t));
267	}
268	static void big_close(void) {
269	  big.px = big_first_px;
270	  free(big.vis_x0);
271	  free(big.vis_x1);
272	  big.vis_x0 = big.vis_x1 = NULL;
273	  free(shadow);
274	  canvas_free(&big);
275	}
