308	static int shadow_push(void *ctx, Canvas *view) {
309	  (void)ctx;
310	  int rows = 0, x0, x1;
311	  for (int y = 0; y < view->h; y++) {
312	    if (!canvas_dirty_row(view, y, &x0, &x1)) continue;
313	    memcpy(shadow + (size_t)y * BW + x0, view->px + (size_t)y * BW + x0,
314	           (size_t)(x1 - x0 + 1) * sizeof(uint16_t));
315	    rows++;
316	  }
317	  return rows;
318	}
319	
320	static void run_swapped(const HackEntry *e, int frames, uint32_t *out) {
321	  const HackEntry *const hacks[] = {e};
322	  HackRunner *r = runner_create_with(&big, hacks, 1);
323	  uint16_t *spare_px = calloc((size_t)BW * BW, sizeof(uint16_t));
324	  PushOverlap *p = push_overlap_create(&big, spare_px, &kOps, shadow_push, NULL);
325	  TEST_ASSERT_NOT_NULL(p);
326	  srandom(1);
327	  runner_start(r, 0);
328	  for (int f = 0; f < frames; f++) {
329	    runner_step(r);
330	    push_overlap_present(p, &big, true);
331	    push_overlap_wait(p);
332	    out[f] = disc_hash(shadow);
333	  }
334	  push_overlap_destroy(p);
335	  runner_destroy(r);
336	  big.px = big_first_px;
337	  free(spare_px);
338	}
