    glVertex3f(ends[i][2], ends[i][3], 0);
    glEnd();
    glXSwapBuffers(dpy, 0);
    clear_all();
    assert_canvas_is(rgb565(255, 0, 0), "a line left stale pixels after a clear");
  }
}

